    sumarDias: function sumarDias(cedula, nombre, genero, salario, salario_integral, diagnostico, tipo_contingencia, prorroga, dias, fecha_inicio, fecha_fin, departamento, ciudad, sede, divipola, edad, evt) {
      var fec = new Date(fecha_inicio);
      var opciones = {
        year: 'numeric',
        month: '2-digit',
        day: '2-digit'
      };
      var tp = tipo_contingencia;
      for (var step = 1; step <= dias; step++) {
        fec.setDate(fec.getDate() + 1);
        // cedula, nombre, genero, salario, diagnostico, tipo_contingencia, prorroga, dias,
        // fecha_inicio, fecha_fin, departamento, ciudad, sede, divipola, edad, rango
        this.diasCostos.push({
          'cedula': cedula,
          'nombre': nombre,
          'genero': genero,
          'diagnostico': diagnostico,
          'departamento': departamento,
          'ciudad': ciudad,
          'sede': sede,
          'divipola': divipola,
          'edad': edad,
          'rango': '',
          'contingencia': tp,
          'cod_evt': evt,
          'consecutivo': step,
          'fecha_inicio': fecha_inicio,
          'fecha_fin': fecha_fin,
          'dias': dias,
          'dia_semana': fec.toLocaleDateString('en-us', {
            weekday: 'short'
          }),
          'dia_mes': fec.toLocaleDateString('en-us', {
            day: 'numeric'
          }),
          'fecha_new': fec.toLocaleDateString('en-us', opciones),
          'ano': fec.toLocaleDateString('en-us', {
            year: 'numeric'
          }),
          'mes': fec.toLocaleDateString('en-us', {
            month: 'long'
          }),
          'sumado': step,
          'prorroga': prorroga,
          'salario': salario,
          'salario_minimo': this.getSalarioMinimo(fec.toLocaleDateString('en-us', {
            year: 'numeric'
          })),
          'salario_integral': salario_integral,
          'asumidos_empresa': 0,
          'aportes_pension': 0,
          'aportes_salud': 0,
          'asumidos_arl': 0,
          'asumidos_eps': 0,
          'otros_costo': 0,
          'costo_total': 0
        });
      }
      console.log('arreglo total -----------------');
      console.log(this.diasCostos);
    },
