    ObtenerRangos: function ObtenerRangos(num) {
      var rs = 'none';
      var con = 0;
      if (!this.newRango) {
        if (this.RangoActivo == 'SI' && this.Rangos.length > 0) {
          this.ran = this.Rangos.sort(function (a, b) {
            return a.maximo - b.maximo;
          });
        } else {
          this.ran = [{
            'maximo': 17,
            'sigla': '< 18',
            'texto': 'Menores de 18',
            'orden': 1
          }, {
            'maximo': 26,
            'sigla': '18-25',
            'texto': '18 - 25 años',
            'orden': 2
          }, {
            'maximo': 36,
            'sigla': '26-35',
            'texto': '26 - 35 años',
            'orden': 3
          }, {
            'maximo': 46,
            'sigla': '36-45',
            'texto': '36 - 45 años',
            'orden': 4
          }, {
            'maximo': 56,
            'sigla': '46-55',
            'texto': '46 - 55 años',
            'orden': 5
          }, {
            'maximo': 66,
            'sigla': '56-65',
            'texto': '56 - 65 años',
            'orden': 6
          }, {
            'maximo': 100,
            'sigla': '> 65',
            'texto': ' Mañores 65 años',
            'orden': 7
          }];
        }
      }
      for (var i = 0; i < this.ran.length; i++) {
        if (num >= this.r_inicio) {
          if (num < this.ran[i].maximo) {
            rs = this.ran[i].sigla;
            break;
          }
        } else {
          rs = 'none';
        }
      }
      return rs;
    },
